async (page) => {
  const sources = ["/**\n * Decode HTML entities in Salesforce UI API displayValue strings.\n * UI API HTML-encodes displayValue; inserting that as a text node shows &#39; literally.\n */\n(function initWohHtmlText(root) {\n  function decodeHtmlEntities(text) {\n    if (text == null) return '';\n    const str = String(text);\n    if (!str.includes('&')) return str;\n    return str\n      .replace(/&nbsp;/gi, '\\u00A0')\n      .replace(/&quot;/g, '\"')\n      .replace(/&apos;/g, \"'\")\n      .replace(/&#x([0-9a-fA-F]+);/g, (_, hex) => {\n        const code = parseInt(hex, 16);\n        return Number.isFinite(code) ? String.fromCodePoint(code) : _;\n      })\n      .replace(/&#(\\d+);/g, (_, dec) => {\n        const code = Number(dec);\n        return Number.isFinite(code) ? String.fromCodePoint(code) : _;\n      })\n      .replace(/&lt;/g, '<')\n      .replace(/&gt;/g, '>')\n      .replace(/&amp;/g, '&');\n  }\n\n  const api = { decodeHtmlEntities };\n\n  if (typeof module !== 'undefined' && module.exports) {\n    module.exports = api;\n  }\n  root.WohHtmlText = api;\n})(typeof window !== 'undefined' ? window : globalThis);\n","/**\n * Pure helpers for resolving Primary NSC Contact (no DOM).\n * Shared by content scripts and Node tests.\n *\n * In Salesforce:\n * - Primary_NSC_Contact__c is a String (person name), often omitted from Full layout\n * - User__c / User__r is a User lookup also labeled \"Primary NSC Contact\"\n */\n(function initWohPrimaryNsc(root) {\n  function cleanPersonName(raw) {\n    const name = String(raw || '')\n      .replace(/\\b(Preview|Open|Show More|Edit|Clear Selection)\\b/gi, ' ')\n      .replace(/\\s+/g, ' ')\n      .trim();\n    if (!name || name.length < 2 || name.length > 80) return '';\n    if (/@/.test(name) || /^primary nsc/i.test(name)) return '';\n    return name;\n  }\n\n  function recordHref(id) {\n    if (!id) return '';\n    if (/^005/.test(id)) return `/lightning/r/User/${id}/view`;\n    if (/^003/.test(id)) return `/lightning/r/Contact/${id}/view`;\n    return `/lightning/r/${id}/view`;\n  }\n\n  function nameFromUiField(field) {\n    if (!field) return { name: '', id: '' };\n    let name = field.displayValue || '';\n    let id = '';\n    const val = field.value;\n\n    if (val && typeof val === 'object') {\n      id = val.id || val.fields?.Id?.value || '';\n      name =\n        name ||\n        val.fields?.Name?.displayValue ||\n        val.fields?.Name?.value ||\n        val.displayValue ||\n        '';\n    } else if (typeof val === 'string') {\n      if (/^(003|005)[a-zA-Z0-9]{12,15}$/.test(val)) {\n        id = val;\n      } else if (!name) {\n        // String field storing the person name (Primary_NSC_Contact__c)\n        name = val;\n      }\n    }\n\n    return { name: cleanPersonName(name), id: id || '' };\n  }\n\n  /**\n   * Pull Primary NSC Contact from a UI API record payload.\n   * Prefers known API names, then User__r, then any *NSC*Contact* field (not email).\n   */\n  function extractPrimaryNscFromUiRecord(record) {\n    const fields = record?.fields || {};\n    const preferred = [\n      'Primary_NSC_Contact__c',\n      'User__r',\n      'User__c',\n      'Primary_NSC_Contact__r',\n      'NSC_Contact__c',\n      'NSC_Contact__r',\n    ];\n\n    const tryField = (apiName) => {\n      const { name, id } = nameFromUiField(fields[apiName]);\n      if (!name) return null;\n      return {\n        name,\n        id,\n        href: recordHref(id),\n        source: 'ui_api',\n        apiName,\n      };\n    };\n\n    for (const apiName of preferred) {\n      const hit = tryField(apiName);\n      if (hit) return hit;\n    }\n\n    for (const apiName of Object.keys(fields)) {\n      if (!/nsc/i.test(apiName) || !/contact/i.test(apiName)) continue;\n      if (/email/i.test(apiName)) continue;\n      const hit = tryField(apiName);\n      if (hit) return hit;\n    }\n\n    return null;\n  }\n\n  /** Field list for an explicit UI API fetch (Full layout often omits these). */\n  const PRIMARY_NSC_UI_FIELDS = [\n    'Appointment__c.Primary_NSC_Contact__c',\n    'Appointment__c.Primary_NSC_Email__c',\n    'Appointment__c.User__c',\n    'Appointment__c.User__r.Name',\n  ];\n\n  const api = {\n    cleanPersonName,\n    extractPrimaryNscFromUiRecord,\n    nameFromUiField,\n    recordHref,\n    PRIMARY_NSC_UI_FIELDS,\n  };\n\n  if (typeof module !== 'undefined' && module.exports) {\n    module.exports = api;\n  }\n  root.WohPrimaryNsc = api;\n})(typeof window !== 'undefined' ? window : globalThis);\n","/**\n * Request # column: show the related Appointment number (REQ- / OPR-),\n * never the WOH Survey Result name (WOH SR-#####).\n */\n(function initWohRequestNumber(root) {\n  function extractAppointmentNumber(text) {\n    const match = String(text || '').match(/\\b(?:REQ|OPR)-\\d+\\b/i);\n    if (!match) return '';\n    return match[0].toUpperCase();\n  }\n\n  function isSalesforceId(value) {\n    return /^(?:a3N|a08|001|003|005)[a-zA-Z0-9]{12,15}$/.test(String(value || ''));\n  }\n\n  function isSurveyResultName(value) {\n    return /WOH\\s*SR[- ]?\\d+/i.test(String(value || ''));\n  }\n\n  function usableAppointmentName(value) {\n    const text = String(value || '').trim();\n    if (!text || isSalesforceId(text) || isSurveyResultName(text)) return '';\n    return extractAppointmentNumber(text) || text;\n  }\n\n  function appointmentNameFromRelatedRecord(record) {\n    const lookup = record?.fields?.Appointment__c;\n    const fromLookup = usableAppointmentName(lookup?.displayValue);\n    if (fromLookup) return fromLookup;\n\n    const rel = record?.fields?.Appointment__r;\n    const relName =\n      rel?.displayValue ||\n      rel?.value?.fields?.Name?.displayValue ||\n      rel?.value?.fields?.Name?.value ||\n      '';\n    return usableAppointmentName(relName);\n  }\n\n  function requestNumberLabel(survey) {\n    return (\n      usableAppointmentName(survey?.appointment_name) ||\n      usableAppointmentName(survey?.req_number) ||\n      extractAppointmentNumber(survey?.survey_result_name) ||\n      '—'\n    );\n  }\n\n  const api = {\n    extractAppointmentNumber,\n    isSurveyResultName,\n    usableAppointmentName,\n    appointmentNameFromRelatedRecord,\n    requestNumberLabel,\n  };\n\n  if (typeof module !== 'undefined' && module.exports) {\n    module.exports = api;\n  }\n  root.WohRequestNumber = api;\n})(typeof window !== 'undefined' ? window : globalThis);\n","/**\n * CSAT answer extraction from Visualforce feedback body text / Q&A pairs.\n * Shared by content scripts and Node tests.\n */\n(function initWohCsatParse(root) {\n  const ENGLISH_ANSWERS =\n    'Very satisfied|Somewhat satisfied|Neither satisfied nor dissatisfied|Somewhat dissatisfied|Very dissatisfied|Satisfied|Dissatisfied';\n  const JAPANESE_ANSWERS =\n    '非常に満足|とても満足|大変満足|やや満足|満足|どちらでもない|やや不満|非常に不満|不満';\n  const FRENCH_ANSWERS =\n    'Très satisfait|Tres satisfait|Très satisfaite|Satisfait|Satisfaite|Ni satisfait ni insatisfait|Peu satisfait|Pas satisfait|Insatisfait|Très insatisfait|Tres insatisfait';\n  const SPANISH_ANSWERS =\n    'Muy satisfecho|Muy satisfecha|Satisfecho|Satisfecha|Ni satisfecho ni insatisfecho|Ni satisfecha ni insatisfecha|Poco satisfecho|Poco satisfecha|Algo insatisfecho|Algo insatisfecha|Insatisfecho|Insatisfecha|Muy insatisfecho|Muy insatisfecha';\n  const ANSWER_GROUP = `(${ENGLISH_ANSWERS}|${JAPANESE_ANSWERS}|${FRENCH_ANSWERS}|${SPANISH_ANSWERS}|[1-5]\\\\s*stars?|[★]{1,5})`;\n\n  function mapQuestionsToFields(questions) {\n    const result = {\n      overall_satisfaction: '',\n      consultant_satisfaction: '',\n      comments: '',\n    };\n\n    for (const { question, answer } of questions) {\n      const q = question.toLowerCase();\n      const qJa = question;\n      // Consultant overall must win before generic \"overall … satisfied\"\n      // (OPR: \"…consultant(s) assigned to this engagement?\").\n      if (\n        q.includes('consultant') ||\n        /コンサルタントにどの程度満足|consultant\\(s\\) assigned/i.test(qJa)\n      ) {\n        result.consultant_satisfaction = answer;\n      } else if (\n        (q.includes('overall') &&\n          (q.includes('satisfied') ||\n            q.includes('request') ||\n            q.includes('experience') ||\n            q.includes('optimization'))) ||\n        /この\\s*Ask-an-Expert|リクエストにどの程度満足|overall experience with this request/i.test(qJa)\n      ) {\n        result.overall_satisfaction = answer;\n      } else if (\n        q.includes('positive') ||\n        q.includes('improvement') ||\n        q.includes('share') ||\n        /良かった点|改善すべき|エクスペリエンス/i.test(qJa)\n      ) {\n        result.comments = answer;\n      }\n    }\n\n    return result;\n  }\n\n  function firstMatch(bodyText, patterns) {\n    for (const re of patterns) {\n      const m = bodyText.match(re);\n      if (m) return m[1].trim();\n    }\n    return '';\n  }\n\n  function extractCsatFromBodyText(bodyText) {\n    const text = String(bodyText || '');\n    const mapped = {\n      overall_satisfaction: '',\n      consultant_satisfaction: '',\n      comments: '',\n    };\n\n    const overallPatterns = [\n      new RegExp(\n        `Overall,\\\\s*how satisfied were you with this (?!consultant)[^?]+\\\\?\\\\s*${ANSWER_GROUP}`,\n        'i'\n      ),\n      new RegExp(\n        `Overall,\\\\s*how satisfied were you with this Ask-an-Expert request\\\\?\\\\s*${ANSWER_GROUP}`,\n        'i'\n      ),\n      new RegExp(`Please rate your overall experience with this request\\\\s*${ANSWER_GROUP}`, 'i'),\n      /全体的に見て、この\\s*Ask-an-Expert\\s*リクエストにどの程度満足していますか？\\s*(非常に満足|とても満足|大変満足|やや満足|満足|どちらでもない|やや不満|非常に不満|不満)/,\n      new RegExp(\n        `Dans l'ensemble, avez-vous été satisfait de cette demande de mise en contact avec un expert\\\\s*\\\\?\\\\s*${ANSWER_GROUP}`,\n        'i'\n      ),\n      new RegExp(\n        `En general,?\\\\s*¿?está satisfech[oa] con esta solicitud(?: de contacto con un experto)?\\\\s*\\\\??\\\\s*${ANSWER_GROUP}`,\n        'i'\n      ),\n    ];\n\n    const consultantPatterns = [\n      new RegExp(\n        `Overall,\\\\s*how satisfied were you with the consultant\\\\(s\\\\) assigned[^?]*\\\\?\\\\s*${ANSWER_GROUP}`,\n        'i'\n      ),\n      new RegExp(\n        `Overall,\\\\s*how satisfied were you with the consultant\\\\(s\\\\) assigned to this request\\\\?\\\\s*${ANSWER_GROUP}`,\n        'i'\n      ),\n      new RegExp(`Please rate the consultant\\\\(s\\\\) assigned to this request\\\\s*${ANSWER_GROUP}`, 'i'),\n      /全体的に見て、このリクエストに割り当てられたコンサルタントにどの程度満足していますか？\\s*(非常に満足|とても満足|大変満足|やや満足|満足|どちらでもない|やや不満|非常に不満|不満)/,\n      new RegExp(\n        `Dans l'ensemble, avez-vous été satisfait du ou des consultants affectés à cette demande\\\\s*\\\\?\\\\s*${ANSWER_GROUP}`,\n        'i'\n      ),\n      new RegExp(\n        `En general,?\\\\s*¿?está satisfech[oa] con (?:el |los |la |las )?consultor(?:es)?(?: asignad[oa]s? a esta solicitud)?\\\\s*\\\\??\\\\s*${ANSWER_GROUP}`,\n        'i'\n      ),\n    ];\n\n    mapped.overall_satisfaction = firstMatch(text, overallPatterns);\n    mapped.consultant_satisfaction = firstMatch(text, consultantPatterns);\n\n    const esLikert =\n      'Muy satisfech[oa]|Satisfech[oa]|Ni satisfecho ni insatisfecho|Ni satisfecha ni insatisfecha|Poco satisfech[oa]|Algo insatisfecho|Algo insatisfecha|Insatisfech[oa]|Muy insatisfecho|Muy insatisfecha';\n\n    if (!mapped.overall_satisfaction) {\n      const fr = text.match(\n        /demande de mise en contact avec un expert\\s*\\?\\s*(Très satisfait[ei]?|Satisfait[ei]?|Ni satisfait ni insatisfait|Peu satisfait|Pas satisfait|Insatisfait|Très insatisfait)/i\n      );\n      if (fr) mapped.overall_satisfaction = fr[1].trim();\n    }\n    if (!mapped.consultant_satisfaction) {\n      const fr = text.match(\n        /consultants affectés à cette demande\\s*\\?\\s*(Très satisfait[ei]?|Satisfait[ei]?|Ni satisfait ni insatisfait|Peu satisfait|Pas satisfait|Insatisfait|Très insatisfait)/i\n      );\n      if (fr) mapped.consultant_satisfaction = fr[1].trim();\n    }\n    if (!mapped.overall_satisfaction) {\n      const es = text.match(\n        new RegExp(`solicitud(?: de contacto con un experto)?\\\\s*\\\\??\\\\s*(${esLikert})`, 'i')\n      );\n      if (es) mapped.overall_satisfaction = es[1].trim();\n    }\n    if (!mapped.consultant_satisfaction) {\n      const es = text.match(\n        new RegExp(`consultor(?:es)?(?: asignad[oa]s? a esta solicitud)?\\\\s*\\\\??\\\\s*(${esLikert})`, 'i')\n      );\n      if (es) mapped.consultant_satisfaction = es[1].trim();\n    }\n\n    const commentsMatch =\n      text.match(\n        /Please share what was positive about your experience and any areas for improvement\\s*(.*?)(?=\\s*Overall, how satisfied|Please rate|$)/i\n      ) ||\n      text.match(/あなたのエクスペリエンスにおいて良かった点や改善すべき点についてお聞かせください\\s*(.+?)(?=\\s*Overall|$)/) ||\n      text.match(\n        /Merci de nous indiquer les aspects positifs de votre expérience et les éventuels points à améliorer\\s*(.+?)(?=\\s*Dans l'ensemble|$)/i\n      ) ||\n      text.match(\n        /(?:Ind[ií]quenos|Por favor,? (?:ind[ií]quenos|comparta)).{0,80}(?:experiencia|mejora).{0,40}\\s*(.+?)(?=\\s*En general|$)/i\n      );\n    if (commentsMatch) mapped.comments = commentsMatch[1].trim();\n\n    if (!mapped.overall_satisfaction) {\n      const jaOverall = text.match(\n        /リクエストにどの程度満足していますか？\\s*(非常に満足|とても満足|大変満足|やや満足|満足|どちらでもない|やや不満|非常に不満|不満)/\n      );\n      if (jaOverall) mapped.overall_satisfaction = jaOverall[1];\n    }\n    if (!mapped.consultant_satisfaction) {\n      const jaConsultant = text.match(\n        /コンサルタントにどの程度満足していますか？\\s*(非常に満足|とても満足|大変満足|やや満足|満足|どちらでもない|やや不満|非常に不満|不満)/\n      );\n      if (jaConsultant) mapped.consultant_satisfaction = jaConsultant[1];\n    }\n\n    return mapped;\n  }\n\n  /**\n   * Likert points for Request CSAT:\n   * Very satisfied=5, Satisfied=4, Neither=3, Dissatisfied=2, Very dissatisfied=1.\n   */\n  function csatPoints(raw) {\n    if (raw == null) return null;\n    const text = String(raw).replace(/\\s+/g, ' ').trim();\n    if (!text) return null;\n\n    const lower = text.toLowerCase().normalize('NFD').replace(/\\p{M}/gu, '');\n\n    if (/^[1-5]$/.test(text)) return Number(text);\n\n    const filledStars = (text.match(/[★✦⭐]/g) || []).length;\n    const starNumber =\n      lower.match(/\\b([1-5])\\s*(?:\\/\\s*5)?\\s*-?\\s*stars?\\b/) ||\n      lower.match(/\\brat(?:ing|ed)?\\s*[:=]?\\s*([1-5])\\b/);\n    const stars = filledStars || (starNumber ? Number(starNumber[1]) : 0);\n    if (stars >= 1 && stars <= 5) return stars;\n\n    if (\n      /very\\s+satisfied|extremely\\s+satisfied|highly\\s+satisfied|completely\\s+satisfied/.test(lower) ||\n      /tres\\s+satisfait|muy\\s+satisfech/.test(lower) ||\n      /非常に満足|とても満足|大変満足/.test(text)\n    ) {\n      return 5;\n    }\n    if (\n      /very\\s+dissatisfied|extremely\\s+dissatisfied/.test(lower) ||\n      /tres\\s+insatisfait|muy\\s+insatisfech/.test(lower) ||\n      /非常に不満|とても不満/.test(text)\n    ) {\n      return 1;\n    }\n    if (\n      /neither/.test(lower) ||\n      /ni\\s+satisfait\\s+ni|ni\\s+satisfech[oa]\\s+ni/.test(lower) ||\n      /どちらでもない/.test(text)\n    ) {\n      return 3;\n    }\n    if (\n      /somewhat\\s+dissatisfied|dissatisfied|dis-satisfied/.test(lower) ||\n      /peu\\s+satisfait|pas\\s+satisfait|insatisfait|poco\\s+satisfech|algo\\s+insatisfech|insatisfech/.test(\n        lower\n      ) ||\n      /やや不満|不満/.test(text)\n    ) {\n      return 2;\n    }\n    if (\n      /somewhat\\s+satisfied|satisfied/.test(lower) ||\n      /satisfait|satisfech/.test(lower) ||\n      /やや満足|満足/.test(text)\n    ) {\n      return 4;\n    }\n\n    return null;\n  }\n\n  function formatAverageDisplay(average) {\n    return (Math.round(average * 10) / 10).toFixed(1);\n  }\n\n  function averageCsatPoints(surveys) {\n    const scores = [];\n    for (const survey of surveys || []) {\n      if (!survey || survey.ok === false) continue;\n      const points = csatPoints(survey.overall_satisfaction);\n      if (points == null) continue;\n      scores.push(points);\n    }\n\n    if (!scores.length) {\n      return {\n        average: null,\n        count: 0,\n        display: '',\n        notice: 'Average points unavailable — no scored surveys in this list.',\n      };\n    }\n\n    const average = scores.reduce((sum, value) => sum + value, 0) / scores.length;\n    const display = formatAverageDisplay(average);\n    return {\n      average: Number(display),\n      count: scores.length,\n      display,\n      notice: `Average points: ${display}`,\n    };\n  }\n\n  const api = {\n    mapQuestionsToFields,\n    extractCsatFromBodyText,\n    csatPoints,\n    averageCsatPoints,\n  };\n\n  if (typeof module !== 'undefined' && module.exports) {\n    module.exports = api;\n  }\n  root.WohCsatParse = api;\n})(typeof window !== 'undefined' ? window : globalThis);\n","/**\n * Shadow-DOM-safe utilities for scraping Salesforce Lightning pages.\n */\n\nfunction walkElements(root) {\n  const results = [];\n  const stack = [root || document];\n\n  while (stack.length) {\n    const node = stack.pop();\n    if (!node) continue;\n\n    if (node.nodeType === Node.ELEMENT_NODE) {\n      results.push(node);\n      if (node.shadowRoot) stack.push(node.shadowRoot);\n      for (let i = node.children.length - 1; i >= 0; i--) {\n        stack.push(node.children[i]);\n      }\n    }\n  }\n  return results;\n}\n\nfunction sleep(ms) {\n  return new Promise((resolve) => setTimeout(resolve, ms));\n}\n\nfunction waitFor(predicate, { timeoutMs = 15000, intervalMs = 300 } = {}) {\n  const start = Date.now();\n  return new Promise((resolve, reject) => {\n    const tick = () => {\n      try {\n        const value = predicate();\n        if (value) return resolve(value);\n      } catch (_) {\n        /* retry */\n      }\n      if (Date.now() - start > timeoutMs) {\n        return reject(new Error('Timed out waiting for page content'));\n      }\n      setTimeout(tick, intervalMs);\n    };\n    tick();\n  });\n}\n\nfunction textOf(el) {\n  if (!el) return '';\n  return (el.innerText || el.textContent || '').replace(/\\s+/g, ' ').trim();\n}\n\nfunction parseRecordId(href) {\n  if (!href) return null;\n  const match = href.match(/\\/(001|003|a3N|a08)[a-zA-Z0-9]{12,18}/);\n  return match ? match[0].slice(1) : null;\n}\n\n/**\n * Extract Account Id from Lightning Account URLs, e.g.\n * /lightning/r/Account/0018000001YEmePAAT/view?ws=...\n */\nfunction parseAccountId(href) {\n  if (!href) return null;\n  const named = String(href).match(/\\/lightning\\/r\\/Account\\/([a-zA-Z0-9]{15,18})(?:\\/|$|\\?)/i);\n  if (named) return named[1];\n  // Classic /001... links\n  const classic = String(href).match(/\\/(001[a-zA-Z0-9]{12,15})(?:\\/|$|\\?)/);\n  return classic ? classic[1] : null;\n}\n\nfunction parseAppointmentId(url) {\n  const href = url || location.href;\n  const named = href.match(/Appointment__c\\/([a-zA-Z0-9]{15,18})/);\n  if (named) return named[1];\n  // Short Lightning URLs: /lightning/r/a3Nxxxxxxxxxxxx/view\n  const short = href.match(/\\/lightning\\/r\\/(a3N[a-zA-Z0-9]{12,15})(?:\\/|$|\\?)/);\n  return short ? short[1] : null;\n}\n\nfunction isAppointmentUrl(url = '') {\n  return (\n    /\\/lightning\\/r\\/Appointment__c\\//.test(url) ||\n    /\\/lightning\\/r\\/a3N[a-zA-Z0-9]{12,15}(?:\\/|$|\\?)/.test(url)\n  );\n}\n\nfunction isAccountUrl(url = '') {\n  return (\n    /\\/lightning\\/r\\/Account\\//i.test(url) ||\n    /\\/lightning\\/r\\/001[a-zA-Z0-9]{12,15}(?:\\/|$|\\?)/.test(url)\n  );\n}\n\n/**\n * Find the Account lookup link on an Appointment Details page\n * (same link you click to open the Account record).\n */\nfunction findAccountOnPage() {\n  const labeled =\n    getFieldByLabel('Account') ||\n    getFieldByLabel('Customer') ||\n    getFieldByLabel('Customer Account');\n\n  if (labeled?.href) {\n    const id = parseAccountId(labeled.href) || labeled.id;\n    if (id) {\n      return {\n        accountId: id,\n        accountName: labeled.value || '',\n        href: labeled.href,\n        source: 'field_label',\n      };\n    }\n  }\n\n  // Shadow-DOM walk: any /lightning/r/Account/{id} link\n  const links = getAllLinks().filter((a) => /\\/lightning\\/r\\/Account\\//i.test(a.href || ''));\n  for (const link of links) {\n    const id = parseAccountId(link.href);\n    if (!id) continue;\n    const name = textOf(link);\n    // Skip empty/utility chrome links\n    if (!name || name.length < 2) continue;\n    return {\n      accountId: id,\n      accountName: name,\n      href: link.href,\n      source: 'account_link',\n    };\n  }\n\n  return null;\n}\n\nfunction normalizePersonName(name) {\n  return String(name || '')\n    .replace(/\\s+/g, ' ')\n    .replace(/\\bPreview\\b/gi, '')\n    .trim()\n    .toLowerCase();\n}\n\nfunction namesMatch(a, b) {\n  const left = normalizePersonName(a);\n  const right = normalizePersonName(b);\n  if (!left || !right) return false;\n  if (left === right) return true;\n  // Allow \"Yanli Huang\" vs \"Huang, Yanli\"\n  const leftParts = left.split(' ').filter(Boolean).sort().join(' ');\n  const rightParts = right.split(' ').filter(Boolean).sort().join(' ');\n  return leftParts === rightParts;\n}\n\nfunction cleanScrapedPersonName(raw) {\n  if (window.WohPrimaryNsc?.cleanPersonName) {\n    return window.WohPrimaryNsc.cleanPersonName(raw);\n  }\n  return String(raw || '')\n    .replace(/\\b(Preview|Open|Show More|Edit|Clear Selection)\\b/gi, ' ')\n    .replace(/\\s+/g, ' ')\n    .trim();\n}\n\n/**\n * Read Primary NSC Contact from the open Appointment page.\n * Prefers Contact/User lookup links inside the field (shadow-DOM safe).\n */\nfunction findPrimaryNscContact() {\n  const labeled =\n    getFieldByLabel('Primary NSC Contact') ||\n    getFieldByLabel('Primary NSC') ||\n    getFieldByLabel('NSC Contact');\n\n  if (labeled?.value) {\n    const name = cleanScrapedPersonName(labeled.value);\n    if (name) {\n      return {\n        name,\n        href: labeled.href || '',\n        id: labeled.id || parseRecordId(labeled.href) || '',\n        source: 'field_label',\n      };\n    }\n  }\n\n  const fromNearLabel = findPrimaryNscContactNearLabel();\n  if (fromNearLabel) return fromNearLabel;\n\n  // document.body.innerText often misses Lightning shadow roots — walk instead\n  const chunks = [];\n  for (const el of walkElements(document)) {\n    if (el.children?.length) continue;\n    const t = textOf(el);\n    if (t) chunks.push(t);\n  }\n  const walked = chunks.join(' ').replace(/\\s+/g, ' ');\n  const match = walked.match(\n    /Primary NSC Contact\\s+((?:Open\\s+)?[A-Za-z][A-Za-z .'-]{1,80}?)\\s+(?:Preview\\s+)?Primary NSC Email/i\n  );\n  if (match) {\n    const name = cleanScrapedPersonName(match[1]);\n    if (name) return { name, href: '', id: '', source: 'walked_text' };\n  }\n\n  return null;\n}\n\nfunction findPrimaryNscContactNearLabel() {\n  const labels = ['primary nsc contact', 'primary nsc', 'nsc contact'];\n  const elements = walkElements(document);\n\n  for (let i = 0; i < elements.length; i++) {\n    const el = elements[i];\n    const text = textOf(el).toLowerCase();\n    if (!labels.includes(text)) continue;\n\n    const container =\n      el.closest('records-record-layout-item, .slds-form__item, [data-target-selection-name]') ||\n      el.parentElement;\n    const scope = container ? walkElements(container) : elements.slice(i, i + 60);\n\n    const contactLink = scope.find(\n      (node) =>\n        node.tagName === 'A' &&\n        /\\/lightning\\/r\\/(Contact|User)\\//i.test(node.href || '')\n    );\n    if (contactLink) {\n      const name = cleanScrapedPersonName(textOf(contactLink));\n      if (name) {\n        return {\n          name,\n          href: contactLink.href || '',\n          id: parseRecordId(contactLink.href) || '',\n          source: 'contact_link',\n        };\n      }\n    }\n  }\n\n  return null;\n}\n\n/**\n * Find a field value on Lightning record pages by label text.\n * Works across shadow roots.\n */\nfunction getFieldByLabel(labelText) {\n  const normalized = labelText.toLowerCase();\n  const elements = walkElements(document);\n  const preferContact = /contact/i.test(labelText) && !/account/i.test(labelText);\n\n  for (const el of elements) {\n    const text = textOf(el);\n    if (!text) continue;\n\n    // Lightning field: label element followed by value in sibling/parent structure\n    // Note: textOf collapses whitespace, so exact label match is the reliable path.\n    if (text.toLowerCase() === normalized) {\n      const container = el.closest('records-record-layout-item, .slds-form__item, [data-target-selection-name]') || el.parentElement;\n      if (!container) continue;\n\n      // querySelector does not pierce nested shadow roots — walk instead\n      const inContainer = walkElements(container);\n      const links = inContainer.filter((node) => node.tagName === 'A' && node.href);\n      const link =\n        (preferContact &&\n          links.find((a) => /\\/lightning\\/r\\/(Contact|User)\\//i.test(a.href))) ||\n        links.find((a) => /\\/lightning\\/r\\/Account\\//i.test(a.href)) ||\n        links.find((a) => /\\/lightning\\/r\\//i.test(a.href)) ||\n        links[0];\n\n      const valueEl =\n        inContainer.find((node) => node.getAttribute?.('slot') === 'outputField') ||\n        inContainer.find((node) =>\n          /^(LIGHTNING-FORMATTED-TEXT|LIGHTNING-FORMATTED-URL|LIGHTNING-FORMATTED-NAME)$/i.test(\n            node.tagName\n          )\n        ) ||\n        inContainer.find((node) => node.classList?.contains('test-id__field-value')) ||\n        link;\n\n      let value = textOf(valueEl) || textOf(link);\n      if (preferContact) value = cleanScrapedPersonName(value);\n      if (value && value.toLowerCase() !== normalized) {\n        return {\n          label: labelText,\n          value,\n          href: link ? link.href : null,\n          id: parseAccountId(link?.href) || parseRecordId(link?.href),\n        };\n      }\n    }\n  }\n\n  // Broader search: walked leaf texts near a label (shadow-safe stand-in for Label\\nValue)\n  for (let i = 0; i < elements.length; i++) {\n    const el = elements[i];\n    if (textOf(el).toLowerCase() !== normalized) continue;\n    const container =\n      el.closest('records-record-layout-item, .slds-form__item, [data-target-selection-name]') ||\n      el.parentElement;\n    if (!container) continue;\n    const leaves = walkElements(container)\n      .filter((node) => !node.children?.length)\n      .map((node) => textOf(node))\n      .filter(Boolean);\n    const valueParts = leaves.filter((t) => t.toLowerCase() !== normalized);\n    let value = valueParts.join(' ').replace(/\\s+/g, ' ').trim();\n    if (preferContact) value = cleanScrapedPersonName(value);\n    if (!value) continue;\n    const link = walkElements(container).find((node) => node.tagName === 'A' && node.href);\n    return {\n      label: labelText,\n      value,\n      href: link ? link.href : null,\n      id: parseRecordId(link?.href),\n    };\n  }\n\n  return null;\n}\n\nfunction getAllLinks() {\n  return walkElements(document).flatMap((el) => (el.tagName === 'A' && el.href ? [el] : []));\n}\n\nfunction findLinkByText(text, { partial = false } = {}) {\n  const target = text.toLowerCase();\n  return getAllLinks().find((a) => {\n    const linkText = textOf(a).toLowerCase();\n    return partial ? linkText.includes(target) : linkText === target;\n  });\n}\n\n/**\n * Scrape Q&A pairs from feedback detail pages.\n * Looks for question text followed by answer text in stacked layout.\n */\nfunction scrapeFeedbackQuestions() {\n  const elements = walkElements(document);\n  const texts = elements\n    .map((el) => textOf(el))\n    .filter((t) => t.length > 10 && t.length < 500);\n\n  const satisfactionKeywords = ['satisfied', 'satisfaction', 'recommend', 'experience', 'improvement', 'positive', 'satisfecho', 'satisfecha', 'consultor', 'experiencia'];\n  const questions = [];\n\n  for (const text of texts) {\n    const lines = text.split('\\n').map((l) => l.trim()).filter(Boolean);\n    if (lines.length < 2) continue;\n\n    const maybeQuestion = lines[0];\n    if (!satisfactionKeywords.some((kw) => maybeQuestion.toLowerCase().includes(kw))) continue;\n\n    questions.push({\n      question: maybeQuestion,\n      answer: lines.slice(1).join(' '),\n    });\n  }\n\n  // Dedupe by question text\n  const seen = new Set();\n  return questions.filter((q) => {\n    if (seen.has(q.question)) return false;\n    seen.add(q.question);\n    return true;\n  });\n}\n\nfunction scrapeRelatedListRows(listTitle) {\n  const titleLower = listTitle.toLowerCase();\n  const elements = walkElements(document);\n\n  for (const el of elements) {\n    const text = textOf(el);\n    if (!text.toLowerCase().includes(titleLower)) continue;\n\n    const container = el.closest('article, section, .slds-card, lst-related-list-view-manager') || el.parentElement;\n    if (!container) continue;\n\n    const links = container.querySelectorAll('a[href]');\n    const rows = [];\n    for (const link of links) {\n      const rowText = textOf(link);\n      if (rowText && /WOH\\s*SR|SR-\\d+/i.test(rowText)) {\n        rows.push({\n          name: rowText,\n          href: link.href,\n          id: parseRecordId(link.href),\n        });\n      }\n    }\n    if (rows.length) return rows;\n  }\n  return [];\n}\n\nfunction isFeedbackPage() {\n  const bodyText = textOf(document.body).toLowerCase();\n  return (\n    bodyText.includes('feedback details') ||\n    bodyText.includes('feedback form') ||\n    bodyText.includes('view submitted feedback')\n  );\n}\n\nfunction mapQuestionsToFields(questions) {\n  if (window.WohCsatParse?.mapQuestionsToFields) {\n    return window.WohCsatParse.mapQuestionsToFields(questions);\n  }\n  return { overall_satisfaction: '', consultant_satisfaction: '', comments: '' };\n}\n\n/**\n * Normalize CSAT answers across English, Japanese, French, Spanish, and star ratings.\n * Returns: 'very_satisfied' | 'satisfied' | 'neither' | 'other' | ''\n *\n * Star mapping:\n * - 5★ → very_satisfied (green)\n * - 4★ → satisfied (yellow)\n * - 3★ → neither (red)\n * - 1–2★ → other (red)\n */\nfunction normalizeCsatLevel(raw) {\n  if (raw == null || raw === '') return '';\n  const text = String(raw).replace(/\\s+/g, ' ').trim();\n  if (!text) return '';\n\n  const lower = text.toLowerCase().normalize('NFD').replace(/\\p{M}/gu, '');\n\n  // Star counts: ★☆✦✩⭐ or \"5 stars\" / \"★★★★★\" / bare \"4\"\n  if (/^[1-5]$/.test(text)) {\n    const n = Number(text);\n    if (n === 5) return 'very_satisfied';\n    if (n === 4) return 'satisfied';\n    if (n === 3) return 'neither';\n    return 'other';\n  }\n  const filledStars = (text.match(/[★✦⭐]/g) || []).length;\n  const starNumber =\n    lower.match(/\\b([1-5])\\s*(?:\\/\\s*5)?\\s*-?\\s*stars?\\b/) ||\n    lower.match(/\\brat(?:ing|ed)?\\s*[:=]?\\s*([1-5])\\b/);\n  const stars = filledStars || (starNumber ? Number(starNumber[1]) : 0);\n  if (stars === 5) return 'very_satisfied';\n  if (stars === 4) return 'satisfied';\n  if (stars === 3) return 'neither';\n  if (stars === 1 || stars === 2) return 'other';\n\n  // Japanese (check longer phrases first)\n  if (/非常に満足|とても満足|大変満足/.test(text)) return 'very_satisfied';\n  if (/やや満足/.test(text)) return 'satisfied';\n  if (/どちらでもない/.test(text)) return 'neither';\n  if (/満足/.test(text) && !/不満/.test(text)) return 'satisfied';\n  if (/非常に不満|とても不満|やや不満|不満/.test(text)) return 'other';\n\n  // French (accent-insensitive via lower)\n  if (/tres\\s+satisfait|tr[eè]s\\s+satisfait|tres\\s+satisfaite/.test(lower) || /Très satisfait/i.test(text)) {\n    return 'very_satisfied';\n  }\n  if (/ni\\s+satisfait\\s+ni\\s+insatisfait|ni satisfait ni/.test(lower)) return 'neither';\n  if (/peu\\s+satisfait|pas\\s+satisfait|insatisfait|tres\\s+insatisfait|tr[eè]s\\s+insatisfait/.test(lower)) {\n    return 'other';\n  }\n  if (/^satisfait[ei]?s?$/.test(lower) || lower === 'satisfait' || lower === 'satisfaite') {\n    return 'satisfied';\n  }\n\n  // Spanish (accent-insensitive via lower)\n  if (/muy\\s+satisfech[oa]s?/.test(lower)) return 'very_satisfied';\n  if (/ni\\s+satisfech[oa]\\s+ni\\s+insatisfech[oa]|ni satisfecho ni|ni satisfecha ni/.test(lower)) {\n    return 'neither';\n  }\n  if (\n    /poco\\s+satisfech[oa]|algo\\s+insatisfech[oa]|muy\\s+insatisfech[oa]|insatisfech[oa]/.test(lower)\n  ) {\n    return 'other';\n  }\n  if (/^satisfech[oa]s?$/.test(lower)) return 'satisfied';\n\n  // English\n  if (/very\\s+satisfied/.test(lower)) return 'very_satisfied';\n  if (/somewhat\\s+satisfied/.test(lower)) return 'satisfied';\n  if (/neither/.test(lower)) return 'neither';\n  if (/^satisfied$/.test(lower) || lower === 'satisfied') return 'satisfied';\n  if (/\\bsatisfied\\b/.test(lower) && !/dis/.test(lower) && !/neither/.test(lower)) {\n    if (/extremely|highly|completely/.test(lower)) return 'very_satisfied';\n  }\n  if (/dissatisfied|dis-satisfied|poor|bad/.test(lower)) return 'other';\n\n  return 'other';\n}\n\nfunction csatRowClass(rawSatisfaction) {\n  const level = normalizeCsatLevel(rawSatisfaction);\n  if (level === 'very_satisfied') return 'csat-green';\n  if (level === 'satisfied') return 'csat-yellow';\n  if (!rawSatisfaction) return 'csat-error';\n  return 'csat-red';\n}\n\n/**\n * Display CSAT in standardized English for the results table.\n * Examples: 非常に満足 / Très satisfait / Muy satisfecho / 5 stars → Very satisfied\n */\nfunction formatCsatEnglish(raw) {\n  if (raw == null || String(raw).trim() === '') return '';\n  const text = String(raw).replace(/\\s+/g, ' ').trim();\n  const lower = text.toLowerCase().normalize('NFD').replace(/\\p{M}/gu, '');\n  const level = normalizeCsatLevel(text);\n\n  if (level === 'very_satisfied') return 'Very satisfied';\n  if (level === 'satisfied') return 'Satisfied';\n  if (level === 'neither') return 'Neither satisfied nor dissatisfied';\n\n  // Finer English labels for negative when we can detect them\n  if (\n    /very\\s+dissatisfied|非常に不満|とても不満|tres\\s+insatisfait|tr[eè]s\\s+insatisfait|muy\\s+insatisfech[oa]/.test(\n      lower\n    ) ||\n    text.includes('非常に不満') ||\n    /Très insatisfait/i.test(text)\n  ) {\n    return 'Very dissatisfied';\n  }\n  if (\n    /somewhat\\s+dissatisfied|やや不満|peu\\s+satisfait|pas\\s+satisfait|poco\\s+satisfech[oa]|algo\\s+insatisfech[oa]/.test(\n      lower\n    ) ||\n    text.includes('やや不満')\n  ) {\n    return 'Somewhat dissatisfied';\n  }\n  if (/^[12]$/.test(text) || /\\b[12]\\s*stars?\\b/.test(lower) || (text.match(/[★]/g) || []).length === 1 || (text.match(/[★]/g) || []).length === 2) {\n    return Number(text) === 1 || /\\b1\\s*stars?\\b/.test(lower) || (text.match(/[★]/g) || []).length === 1\n      ? 'Very dissatisfied'\n      : 'Somewhat dissatisfied';\n  }\n  if (/dissatisfied|insatisfait|insatisfech|不満/.test(lower) || text.includes('不満')) return 'Dissatisfied';\n\n  return 'Other';\n}\n\nfunction extractStarRatingsFromDoc(doc) {\n  const ratings = [];\n\n  const selects = [...doc.querySelectorAll('select.star-rating, select[class*=\"star-rating\"]')];\n  for (const select of selects) {\n    const selected =\n      select.querySelector('option[selected], option[selected=\"selected\"]') ||\n      [...select.options].find((o) => o.selected);\n    const val = (selected?.value || select.value || '').trim();\n    if (/^[1-5]$/.test(val)) ratings.push(`${val} stars`);\n  }\n\n  if (ratings.length) return ratings;\n\n  // Barrating widget fallback (after JS render)\n  const current = [...doc.querySelectorAll('.br-current-rating')]\n    .map((el) => textOf(el))\n    .filter((t) => /^[1-5]$/.test(t));\n  return current.map((n) => `${n} stars`);\n}\n\nfunction extractStarRatingsFromHtml(html) {\n  const ratings = [];\n  const selectRe =\n    /<select[^>]*class=\"[^\"]*star-rating[^\"]*\"[^>]*>([\\s\\S]*?)<\\/select>/gi;\n  let match;\n  while ((match = selectRe.exec(html))) {\n    const block = match[1];\n    const selected = block.match(/<option[^>]*value=\"([1-5])\"[^>]*selected[^>]*>/i)\n      || block.match(/<option[^>]*selected[^>]*value=\"([1-5])\"[^>]*>/i);\n    if (selected) ratings.push(`${selected[1]} stars`);\n  }\n  if (ratings.length) return ratings;\n\n  const currentRe = /class=\"[^\"]*br-current-rating[^\"]*\"[^>]*>\\s*([1-5])\\s*</gi;\n  while ((match = currentRe.exec(html))) {\n    ratings.push(`${match[1]} stars`);\n  }\n  return ratings;\n}\n\n/**\n * Parse Visualforce WHT_FeedBackDetail HTML (from fetch or live document).\n */\nfunction parseFeedbackHtml(html) {\n  const doc = new DOMParser().parseFromString(html, 'text/html');\n  const bodyText = textOf(doc.body);\n  const rawHtml = String(html || '');\n\n  const submittedLine = bodyText.match(\n    /Submitted\\s+(\\d{1,2}\\/\\d{1,2}\\/\\d{4})\\s+By:\\s*(.+?)(?:\\s+Request:|$)/i\n  );\n  const reqMatch = window.WohRequestNumber?.extractAppointmentNumber\n    ? window.WohRequestNumber.extractAppointmentNumber(bodyText)\n    : bodyText.match(/\\b(?:REQ|OPR)-\\d+\\b/i)?.[0] || '';\n\n  const mapped = {\n    overall_satisfaction: '',\n    consultant_satisfaction: '',\n    comments: '',\n  };\n\n  // 1) Star-rating widgets (most common for \"Please rate…\" forms)\n  const starRatings =\n    extractStarRatingsFromDoc(doc).length\n      ? extractStarRatingsFromDoc(doc)\n      : extractStarRatingsFromHtml(rawHtml);\n  if (starRatings[0]) mapped.overall_satisfaction = starRatings[0];\n  if (starRatings[1]) mapped.consultant_satisfaction = starRatings[1];\n\n  // 2) Likert text answers (AAE, Optimization Package / OPR, JA/FR/ES)\n  if (!mapped.overall_satisfaction || !mapped.consultant_satisfaction) {\n    const fromText = window.WohCsatParse?.extractCsatFromBodyText\n      ? window.WohCsatParse.extractCsatFromBodyText(bodyText)\n      : { overall_satisfaction: '', consultant_satisfaction: '', comments: '' };\n    mapped.overall_satisfaction = mapped.overall_satisfaction || fromText.overall_satisfaction;\n    mapped.consultant_satisfaction = mapped.consultant_satisfaction || fromText.consultant_satisfaction;\n    mapped.comments = mapped.comments || fromText.comments;\n  }\n\n  if (!mapped.overall_satisfaction || !mapped.consultant_satisfaction) {\n    const fromDom = mapQuestionsToFields(scrapeFeedbackQuestionsFromRoot(doc));\n    mapped.overall_satisfaction = mapped.overall_satisfaction || fromDom.overall_satisfaction;\n    mapped.consultant_satisfaction = mapped.consultant_satisfaction || fromDom.consultant_satisfaction;\n    mapped.comments = mapped.comments || fromDom.comments;\n  }\n\n  let consultantName = '';\n  const consultantMatch = bodyText.match(\n    /Consultants?\\s+([A-Za-z][A-Za-z .'-]{1,60})(?:\\s+Product|\\s+Sub Product|\\s+Feedback)/i\n  );\n  if (consultantMatch) consultantName = consultantMatch[1].trim();\n\n  let product = '';\n  const productMatch = bodyText.match(/Product\\s+(.+?)\\s+Sub Product/i);\n  if (productMatch) product = productMatch[1].trim();\n\n  let subProduct = '';\n  const subMatch = bodyText.match(/Sub Product\\s+(.+?)\\s+Feedback Form/i);\n  if (subMatch) subProduct = subMatch[1].trim();\n\n  return {\n    req_number: reqMatch || '',\n    submitted_at: submittedLine ? submittedLine[1] : '',\n    submitted_by: submittedLine ? submittedLine[2].trim() : '',\n    consultant_name: consultantName,\n    product,\n    sub_product: subProduct,\n    overall_satisfaction: mapped.overall_satisfaction,\n    consultant_satisfaction: mapped.consultant_satisfaction,\n    comments: mapped.comments,\n    overall_satisfaction_level: normalizeCsatLevel(mapped.overall_satisfaction),\n    body_excerpt: bodyText.slice(0, 400),\n  };\n}\n\nfunction scrapeFeedbackQuestionsFromRoot(root) {\n  const elements = walkElements(root);\n  const texts = elements\n    .map((el) => textOf(el))\n    .filter((t) => t.length > 10 && t.length < 500);\n\n  const satisfactionKeywords = [\n    'satisfied',\n    'satisfaction',\n    'recommend',\n    'experience',\n    'improvement',\n    'positive',\n    '満足',\n    'コンサルタント',\n    'エクスペリエンス',\n    'satisfait',\n    'consultants',\n    'expérience',\n    'satisfecho',\n    'satisfecha',\n    'consultor',\n    'experiencia',\n  ];\n  const questions = [];\n\n  for (const text of texts) {\n    const parts = text.split('\\n').map((l) => l.trim()).filter(Boolean);\n    if (parts.length < 2) continue;\n    const maybeQuestion = parts[0];\n    if (!satisfactionKeywords.some((kw) => maybeQuestion.toLowerCase().includes(kw.toLowerCase()) || maybeQuestion.includes(kw)))\n      continue;\n    questions.push({ question: maybeQuestion, answer: parts.slice(1).join(' ') });\n  }\n\n  const seen = new Set();\n  return questions.filter((q) => {\n    if (seen.has(q.question)) return false;\n    seen.add(q.question);\n    return true;\n  });\n}\n\n// Expose for other content scripts (same isolated world per file, but functions are global in IIFE-less scripts)\nwindow.WohScrape = {\n  walkElements,\n  sleep,\n  waitFor,\n  textOf,\n  parseRecordId,\n  parseAccountId,\n  parseAppointmentId,\n  isAppointmentUrl,\n  isAccountUrl,\n  getFieldByLabel,\n  findAccountOnPage,\n  findPrimaryNscContact,\n  normalizePersonName,\n  namesMatch,\n  normalizeCsatLevel,\n  formatCsatEnglish,\n  csatRowClass,\n  findLinkByText,\n  scrapeFeedbackQuestions,\n  scrapeRelatedListRows,\n  isFeedbackPage,\n  mapQuestionsToFields,\n  parseFeedbackHtml,\n  scrapeFeedbackQuestionsFromRoot,\n};\n","/**\n * Salesforce Lightning UI API helpers (uses the logged-in browser session).\n */\n(function initWohSfApi() {\n  const API_VERSION = 'v59.0';\n  const RELATED_LIST = 'WOH_Survey_Results__r';\n\n  async function fetchJson(pathOrUrl) {\n    const url = pathOrUrl.startsWith('http')\n      ? pathOrUrl\n      : `${location.origin}${pathOrUrl.startsWith('/') ? '' : '/'}${pathOrUrl}`;\n    const response = await fetch(url, { credentials: 'include' });\n    const text = await response.text();\n    let json = null;\n    try {\n      json = JSON.parse(text);\n    } catch (_) {\n      /* non-JSON */\n    }\n    if (!response.ok) {\n      const message =\n        (Array.isArray(json) && json[0]?.message) ||\n        json?.message ||\n        `HTTP ${response.status}`;\n      throw new Error(message);\n    }\n    return json;\n  }\n\n  async function uiApiRecord(recordId) {\n    return fetchJson(\n      `/services/data/${API_VERSION}/ui-api/records/${encodeURIComponent(recordId)}?layoutTypes=Full&modes=View`\n    );\n  }\n\n  /** Fetch specific fields (use when Full layout omits them). */\n  async function uiApiRecordFields(recordId, fields) {\n    const list = Array.isArray(fields) ? fields.filter(Boolean) : [];\n    if (!list.length) return uiApiRecord(recordId);\n    const param = list.map(encodeURIComponent).join(',');\n    return fetchJson(\n      `/services/data/${API_VERSION}/ui-api/records/${encodeURIComponent(recordId)}?fields=${param}`\n    );\n  }\n\n  function fieldValue(record, apiName) {\n    const field = record?.fields?.[apiName];\n    if (!field) return null;\n    if (field.value != null && typeof field.value === 'object' && 'value' in field.value) {\n      return field.value.value;\n    }\n    return field.value ?? field.displayValue ?? null;\n  }\n\n  function decodeDisplayText(text) {\n    if (window.WohHtmlText?.decodeHtmlEntities) {\n      return window.WohHtmlText.decodeHtmlEntities(text);\n    }\n    return text == null ? '' : String(text);\n  }\n\n  function fieldDisplay(record, apiName) {\n    const field = record?.fields?.[apiName];\n    if (!field) return '';\n    if (field.displayValue) return decodeDisplayText(field.displayValue);\n    const value = fieldValue(record, apiName);\n    return value == null ? '' : decodeDisplayText(String(value));\n  }\n\n  /**\n   * Page through a related list until exhausted (or maxPages).\n   */\n  async function relatedListAll(parentId, relatedListId = RELATED_LIST, fields = [], { pageSize = 50, maxPages = 40 } = {}) {\n    const fieldParam = fields.length ? `&fields=${fields.map(encodeURIComponent).join(',')}` : '';\n    let pageToken = '0';\n    const records = [];\n\n    for (let page = 0; page < maxPages; page++) {\n      const path =\n        `/services/data/${API_VERSION}/ui-api/related-list-records/` +\n        `${encodeURIComponent(parentId)}/${encodeURIComponent(relatedListId)}` +\n        `?pageSize=${pageSize}&pageToken=${encodeURIComponent(pageToken)}${fieldParam}`;\n\n      const json = await fetchJson(path);\n      records.push(...(json.records || []));\n      if (!json.nextPageToken) break;\n      pageToken = String(json.nextPageToken);\n    }\n\n    return records;\n  }\n\n  /**\n   * Ask the background page to fetch VF HTML (avoids page CORS on vf.force.com redirects).\n   */\n  async function fetchFeedbackHtml(appointmentId) {\n    const api = globalThis.browser ?? globalThis.chrome;\n    if (!api?.runtime?.sendMessage) {\n      throw new Error('Extension runtime unavailable for feedback fetch');\n    }\n    const response = await api.runtime.sendMessage({\n      type: 'FETCH_FEEDBACK_HTML',\n      appointmentId,\n    });\n    if (!response?.ok) {\n      throw new Error(response?.error || 'Background feedback fetch failed');\n    }\n    return { html: response.html, url: response.url };\n  }\n\n  /** Used by background.js — not subject to page CORS. */\n  async function fetchFeedbackHtmlDirect(appointmentId) {\n    const candidates = [\n      `https://workday.lightning.force.com/apex/WHT_FeedBackDetail?appointmentId=${encodeURIComponent(appointmentId)}`,\n      `https://workday.lightning.force.com/apex/WHT_FeedbackDetail?appointmentId=${encodeURIComponent(appointmentId)}`,\n      `https://workday--c.vf.force.com/apex/WHT_FeedBackDetail?appointmentId=${encodeURIComponent(appointmentId)}`,\n      `https://workday--c.vf.force.com/apex/WHT_FeedbackDetail?appointmentId=${encodeURIComponent(appointmentId)}`,\n    ];\n    const errors = [];\n    for (const url of candidates) {\n      try {\n        const response = await fetch(url, {\n          credentials: 'include',\n          redirect: 'follow',\n          headers: { Accept: 'text/html' },\n        });\n        const html = await response.text();\n        if (!response.ok) {\n          errors.push(`${url} → HTTP ${response.status}`);\n          continue;\n        }\n        if (/Feedback Form|how satisfied|Feedback Details/i.test(html) || html.length > 800) {\n          return { html, url: response.url || url };\n        }\n        errors.push(`${url} → unexpected HTML (${html.length} bytes)`);\n      } catch (err) {\n        errors.push(`${url} → ${err.message || err}`);\n      }\n    }\n    throw new Error(`Could not load feedback page: ${errors.join('; ')}`);\n  }\n\n  window.WohSfApi = {\n    API_VERSION,\n    RELATED_LIST,\n    uiApiRecord,\n    uiApiRecordFields,\n    fieldValue,\n    fieldDisplay,\n    relatedListAll,\n    fetchFeedbackHtml,\n    fetchFeedbackHtmlDirect,\n  };\n})();\n","/**\n * Persistent in-page results panel (stays until user clicks X).\n * Cache: browser.storage.local, 12-hour TTL per Account Id.\n */\n(function initWohSurveyPanel() {\n  const api = globalThis.browser ?? globalThis.chrome;\n  const PANEL_ID = 'woh-account-surveys-panel-host';\n  const CACHE_KEY = 'accountSurveyCache';\n  const CACHE_TTL_MS = 12 * 60 * 60 * 1000;\n\n  const PANEL_CSS = `\n        :host { all: initial; }\n        .panel {\n          font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", sans-serif;\n          width: min(560px, calc(100vw - 32px));\n          max-height: calc(100vh - 96px);\n          overflow: auto;\n          background: #fff;\n          color: #1f1f1f;\n          border-radius: 12px;\n          box-shadow: 0 8px 28px rgba(0,0,0,.22);\n          border: 1px solid #e5e5e5;\n        }\n        .header {\n          display: flex;\n          align-items: flex-start;\n          justify-content: space-between;\n          gap: 12px;\n          padding: 12px 14px 8px;\n          border-bottom: 1px solid #eee;\n          position: sticky;\n          top: 0;\n          background: #fff;\n          z-index: 1;\n        }\n        .title { font-size: 15px; font-weight: 700; margin: 0; }\n        .subtitle { font-size: 12px; color: #666; margin: 2px 0 0; }\n        .account { font-size: 12px; font-weight: 600; margin-top: 6px; color: #333; }\n        .close {\n          border: none;\n          background: transparent;\n          font-size: 22px;\n          line-height: 1;\n          cursor: pointer;\n          color: #666;\n          padding: 0 4px;\n          border-radius: 6px;\n        }\n        .close:hover { background: #f0f0f0; color: #111; }\n        .body { padding: 10px 14px 14px; }\n        .status-line { font-size: 12px; color: #555; margin-bottom: 8px; }\n        .cache { font-size: 11px; color: #666; margin-bottom: 8px; }\n        .notice {\n          font-size: 12px;\n          margin: 0 0 10px;\n          padding: 8px 10px;\n          border-radius: 8px;\n          background: #fff4e5;\n          border: 1px solid #f0d2a0;\n          color: #6a4b00;\n          line-height: 1.35;\n        }\n        .notice.ok {\n          background: #e8f5e9;\n          border-color: #a5d6a7;\n          color: #1b5e20;\n        }\n        .notice.avg {\n          background: #e8f4fd;\n          border-color: #90caf9;\n          color: #0d47a1;\n        }\n        .notice.avg .avg-value {\n          font-weight: 700;\n          font-size: 13px;\n        }\n        .primary-nsc { font-weight: 700; }\n        .linkish {\n          border: none;\n          background: none;\n          color: #0176d3;\n          cursor: pointer;\n          padding: 0;\n          font-size: 11px;\n          text-decoration: underline;\n        }\n        .error { color: #b00020; font-size: 13px; }\n        table { width: 100%; border-collapse: collapse; font-size: 12px; }\n        th {\n          text-align: left;\n          font-size: 11px;\n          color: #555;\n          padding: 6px 8px;\n          border-bottom: 1px solid #ddd;\n          background: #f7f7f7;\n        }\n        td { padding: 8px; border-bottom: 1px solid #eee; vertical-align: top; }\n        a { color: #0176d3; font-weight: 600; text-decoration: none; }\n        a:hover { text-decoration: underline; }\n        tr.csat-green td { background: #d4edda; }\n        tr.csat-yellow td { background: #fff3cd; }\n        tr.csat-red td { background: #f8d7da; }\n        tr.csat-error td { background: #f5f5f5; color: #666; }\n  `;\n\n  function el(tag, attrs = {}, ...children) {\n    const node = document.createElement(tag);\n    for (const [key, value] of Object.entries(attrs)) {\n      if (value == null || value === false) continue;\n      if (key === 'className') node.className = value;\n      else node.setAttribute(key, String(value));\n    }\n    for (const child of children) {\n      if (child == null || child === false) continue;\n      node.append(child);\n    }\n    return node;\n  }\n\n  function csatRowClass(overallSatisfaction) {\n    if (window.WohScrape?.csatRowClass) {\n      return window.WohScrape.csatRowClass(overallSatisfaction);\n    }\n    const value = String(overallSatisfaction || '')\n      .trim()\n      .toLowerCase()\n      .replace(/\\s+/g, ' ');\n    if (value === 'very satisfied' || value.includes('非常に満足') || /5\\s*stars?/.test(value) || (String(overallSatisfaction || '').match(/[★]/g) || []).length >= 5) {\n      return 'csat-green';\n    }\n    if (value === 'satisfied' || value === '満足' || value.includes('やや満足') || /4\\s*stars?/.test(value)) {\n      return 'csat-yellow';\n    }\n    return 'csat-red';\n  }\n\n  async function readCache(accountId) {\n    const { [CACHE_KEY]: cache = {} } = await api.storage.local.get(CACHE_KEY);\n    const entry = cache[accountId];\n    if (!entry?.fetchedAt || !entry?.payload) return null;\n    if (Date.now() - entry.fetchedAt > CACHE_TTL_MS) return null;\n    return entry;\n  }\n\n  async function writeCache(accountId, payload) {\n    const { [CACHE_KEY]: cache = {} } = await api.storage.local.get(CACHE_KEY);\n    cache[accountId] = { fetchedAt: Date.now(), payload };\n    // prune expired\n    const now = Date.now();\n    for (const [id, entry] of Object.entries(cache)) {\n      if (!entry?.fetchedAt || now - entry.fetchedAt > CACHE_TTL_MS) delete cache[id];\n    }\n    await api.storage.local.set({ [CACHE_KEY]: cache });\n  }\n\n  function ensureHost() {\n    let host = document.getElementById(PANEL_ID);\n    if (host) return host;\n    host = document.createElement('div');\n    host.id = PANEL_ID;\n    host.style.all = 'initial';\n    host.style.position = 'fixed';\n    host.style.zIndex = '2147483646';\n    host.style.top = '72px';\n    host.style.right = '16px';\n    document.documentElement.appendChild(host);\n    host.attachShadow({ mode: 'open' });\n    return host;\n  }\n\n  function closePanel() {\n    document.getElementById(PANEL_ID)?.remove();\n  }\n\n  function reqNode(survey, { errorRow = false } = {}) {\n    const label = window.WohRequestNumber?.requestNumberLabel\n      ? window.WohRequestNumber.requestNumberLabel(survey)\n      : survey.req_number || survey.appointment_name || '—';\n    const href = errorRow\n      ? survey.feedback_url || survey.appointment_url || ''\n      : survey.feedback_url || '';\n    if (href) {\n      return el('a', { href, target: '_blank', rel: 'noreferrer' }, label);\n    }\n    return label;\n  }\n\n  function customerNode(survey) {\n    const name = survey.submitted_by || '—';\n    if (survey.is_primary_nsc) {\n      return el('strong', { className: 'primary-nsc' }, name);\n    }\n    return name;\n  }\n\n  function primaryNoticeNode(payload) {\n    if (payload?.primary_nsc_contact && payload?.primary_nsc_matched) {\n      return el(\n        'div',\n        { className: 'notice ok' },\n        'Primary NSC Contact ',\n        el('strong', {}, payload.primary_nsc_contact),\n        ' appears in this list (bold).'\n      );\n    }\n    if (payload?.primary_nsc_contact) {\n      return el(\n        'div',\n        { className: 'notice' },\n        payload.primary_nsc_notice ||\n          `${payload.primary_nsc_contact} (Primary NSC Contact) has not submitted a survey in this recent list.`\n      );\n    }\n    return el('div', { className: 'notice' }, 'Primary NSC Contact not found on this request.');\n  }\n\n  function averageNoticeNode(payload) {\n    const display = payload?.csat_average_display;\n    if (display) {\n      return el(\n        'div',\n        { className: 'notice avg' },\n        'Average points: ',\n        el('strong', { className: 'avg-value' }, display)\n      );\n    }\n    return el(\n      'div',\n      { className: 'notice' },\n      payload?.csat_average_notice || 'Average points unavailable — no scored surveys in this list.'\n    );\n  }\n\n  function contextNoticeNode(payload) {\n    if (payload?.page_context === 'account') {\n      return averageNoticeNode(payload);\n    }\n    return primaryNoticeNode(payload);\n  }\n\n  function surveyRow(survey) {\n    if (!survey.ok) {\n      return el(\n        'tr',\n        { className: 'csat-error' },\n        el('td', {}, reqNode(survey, { errorRow: true })),\n        el('td', {}, survey.submitted_at || '—'),\n        el('td', {}, customerNode(survey)),\n        el('td', {}, survey.error || 'Failed')\n      );\n    }\n    const csat =\n      (window.WohScrape?.formatCsatEnglish\n        ? window.WohScrape.formatCsatEnglish(survey.overall_satisfaction)\n        : survey.overall_satisfaction) || '—';\n    return el(\n      'tr',\n      { className: csatRowClass(survey.overall_satisfaction) },\n      el('td', {}, reqNode(survey)),\n      el('td', {}, survey.submitted_at || '—'),\n      el('td', {}, customerNode(survey)),\n      el('td', {}, csat)\n    );\n  }\n\n  function bodyNodes({ statusText, payload, fromCache, error }) {\n    if (error) {\n      return [el('div', { className: 'error' }, String(error))];\n    }\n    if (!payload) {\n      return [el('div', { className: 'status-line' }, statusText || 'Loading…')];\n    }\n    if (!(payload.surveys || []).length) {\n      const nodes = [el('div', { className: 'status-line' }, payload.message || 'No surveys found.')];\n      if (payload.page_context !== 'account') {\n        nodes.push(primaryNoticeNode(payload));\n      }\n      return nodes;\n    }\n    const nodes = [el('div', { className: 'status-line' }, statusText || '')];\n    if (fromCache) {\n      nodes.push(\n        el(\n          'div',\n          { className: 'cache' },\n          'Cached result (valid up to 12 hours). ',\n          el('button', { type: 'button', className: 'linkish', id: 'woh-refresh' }, 'Refresh now')\n        )\n      );\n    }\n    nodes.push(contextNoticeNode(payload));\n    nodes.push(\n      el(\n        'table',\n        {},\n        el(\n          'thead',\n          {},\n          el(\n            'tr',\n            {},\n            el('th', {}, 'Request #'),\n            el('th', {}, 'Survey date'),\n            el('th', {}, 'Customer'),\n            el('th', {}, 'Request CSAT')\n          )\n        ),\n        el('tbody', {}, ...(payload.surveys || []).map(surveyRow))\n      )\n    );\n    return nodes;\n  }\n\n  function renderPanel({ statusText, payload, fromCache, error }) {\n    const host = ensureHost();\n    const root = host.shadowRoot;\n    const decodeText = window.WohHtmlText?.decodeHtmlEntities || ((text) => String(text ?? ''));\n    const accountName = payload?.account_name ? decodeText(payload.account_name) : '';\n    const accountLabel = payload\n      ? accountName\n        ? `${accountName} (${payload.account_id || ''})`\n        : payload.account_id || ''\n      : '';\n\n    const headerText = el(\n      'div',\n      {},\n      el('p', { className: 'title' }, 'Survey History Tracking'),\n      el('p', { className: 'subtitle' }, '10 most recent surveys for this Account'),\n      accountLabel ? el('div', { className: 'account' }, `Account: ${accountLabel}`) : null\n    );\n\n    const panel = el(\n      'div',\n      { className: 'panel', role: 'dialog', 'aria-label': 'Survey History Tracking' },\n      el(\n        'div',\n        { className: 'header' },\n        headerText,\n        el('button', { type: 'button', className: 'close', id: 'woh-close', title: 'Close', 'aria-label': 'Close' }, '×')\n      ),\n      el('div', { className: 'body' }, ...bodyNodes({ statusText, payload, fromCache, error }))\n    );\n\n    const style = document.createElement('style');\n    style.textContent = PANEL_CSS;\n    root.replaceChildren(style, panel);\n\n    root.getElementById('woh-close')?.addEventListener('click', closePanel);\n    root.getElementById('woh-refresh')?.addEventListener('click', () => {\n      window.dispatchEvent(new CustomEvent('woh-survey-refresh'));\n    });\n  }\n\n  window.WohSurveyPanel = {\n    CACHE_TTL_MS,\n    readCache,\n    writeCache,\n    renderPanel,\n    closePanel,\n    setStatus(text) {\n      renderPanel({ statusText: text, payload: null });\n    },\n    showPayload(payload, { fromCache = false, statusText = '' } = {}) {\n      const okCount = (payload.surveys || []).filter((s) => s.ok).length;\n      const total = (payload.surveys || []).length;\n      renderPanel({\n        payload,\n        fromCache,\n        statusText:\n          statusText ||\n          (fromCache\n            ? `Showing ${okCount} of ${total} surveys (from cache).`\n            : `Showing ${okCount} of ${total} most recent surveys.`),\n      });\n    },\n    showError(error) {\n      renderPanel({ error: String(error), payload: null });\n    },\n  };\n})();\n","/**\n * Runs on Appointment__c and Account record pages.\n * Toolbar click → show persistent panel with Account's 10 newest surveys (12h cache).\n * Account pages show average Request CSAT points instead of Primary NSC status.\n */\n\n(async function initAppointmentScraper() {\n  if (window.__wohAppointmentScraperInit) return;\n  window.__wohAppointmentScraperInit = true;\n\n  const api = globalThis.browser ?? globalThis.chrome;\n  const { parseAppointmentId, parseAccountId, isAppointmentUrl, isAccountUrl, findAccountOnPage, findPrimaryNscContact, namesMatch, parseFeedbackHtml, waitFor, getFieldByLabel } =\n    window.WohScrape;\n  const { uiApiRecord, uiApiRecordFields, fieldValue, fieldDisplay, relatedListAll, fetchFeedbackHtml } =\n    window.WohSfApi;\n  const { extractPrimaryNscFromUiRecord, PRIMARY_NSC_UI_FIELDS } = window.WohPrimaryNsc || {};\n  const { appointmentNameFromRelatedRecord, extractAppointmentNumber, isSurveyResultName } =\n    window.WohRequestNumber || {};\n  const panel = window.WohSurveyPanel;\n\n  const TOP_N = 10;\n  const RELATED_FIELDS = ['Id', 'Name', 'Appointment__c', 'Date_Time_Survey_Submitted__c', 'Survey_Author__c'];\n  const INFLIGHT_STALE_MS = 90_000;\n\n  let inflight = null;\n  let inflightStartedAt = 0;\n\n  function emitProgress(text) {\n    panel?.setStatus(text);\n  }\n\n  function sortKey(record) {\n    const raw =\n      fieldValue(record, 'Date_Time_Survey_Submitted__c') ||\n      record.lastModifiedDate ||\n      '';\n    const ms = Date.parse(raw);\n    return Number.isFinite(ms) ? ms : 0;\n  }\n\n  async function resolvePrimaryNscFromApi(appointmentId) {\n    if (!extractPrimaryNscFromUiRecord || !uiApiRecordFields) return null;\n    try {\n      const fields = PRIMARY_NSC_UI_FIELDS || [\n        'Appointment__c.Primary_NSC_Contact__c',\n        'Appointment__c.User__c',\n        'Appointment__c.User__r.Name',\n      ];\n      const record = await uiApiRecordFields(appointmentId, fields);\n      return extractPrimaryNscFromUiRecord(record);\n    } catch (err) {\n      console.warn('[WOH Survey] Primary NSC UI API lookup failed', err);\n      return null;\n    }\n  }\n\n  function detectPageContext(url = location.href) {\n    if (isAppointmentUrl ? isAppointmentUrl(url) : Boolean(parseAppointmentId(url))) {\n      return 'appointment';\n    }\n    if (isAccountUrl ? isAccountUrl(url) : Boolean(parseAccountId(url))) {\n      return 'account';\n    }\n    return null;\n  }\n\n  async function resolveAccountRecord() {\n    const accountId = parseAccountId(location.href);\n    if (!accountId) {\n      throw new Error('Could not resolve Account from this page. Reload and try again.');\n    }\n\n    emitProgress('Loading Account…');\n    let accountName = '';\n    try {\n      const record = await uiApiRecord(accountId);\n      accountName = fieldDisplay(record, 'Name') || fieldValue(record, 'Name') || '';\n    } catch (err) {\n      console.warn('[WOH Survey] UI API account lookup failed', err);\n    }\n\n    if (!accountName && getFieldByLabel) {\n      const labeled = getFieldByLabel('Account Name') || getFieldByLabel('Account');\n      accountName = labeled?.value || '';\n    }\n\n    return {\n      accountId,\n      accountName,\n      appointmentName: '',\n      appointmentId: '',\n      accountHref: `${location.origin}/lightning/r/Account/${accountId}/view`,\n      source: 'account_page',\n      primaryNsc: null,\n    };\n  }\n\n  async function resolveAccount(appointmentId) {\n    emitProgress('Resolving Account…');\n\n    let primaryNsc = await resolvePrimaryNscFromApi(appointmentId);\n\n    try {\n      const record = await uiApiRecord(appointmentId);\n      const accountId = fieldValue(record, 'Account__c');\n      const accountName = fieldDisplay(record, 'Account__r') || fieldDisplay(record, 'Account__c');\n      const appointmentName = fieldDisplay(record, 'Name');\n      if (!primaryNsc && extractPrimaryNscFromUiRecord) {\n        primaryNsc = extractPrimaryNscFromUiRecord(record);\n      }\n      if (accountId) {\n        return {\n          accountId,\n          accountName,\n          appointmentName,\n          appointmentId,\n          accountHref: `${location.origin}/lightning/r/Account/${accountId}/view`,\n          source: 'ui_api',\n          primaryNsc,\n        };\n      }\n    } catch (err) {\n      console.warn('[WOH Survey] UI API appointment lookup failed', err);\n    }\n\n    try {\n      await waitFor(() => Boolean(findAccountOnPage()), { timeoutMs: 5000, intervalMs: 300 });\n    } catch (_) {\n      /* continue */\n    }\n\n    const fromPage = findAccountOnPage();\n    if (fromPage?.accountId) {\n      return {\n        accountId: fromPage.accountId,\n        accountName: fromPage.accountName || '',\n        appointmentName: '',\n        appointmentId,\n        accountHref: fromPage.href || '',\n        source: fromPage.source,\n        primaryNsc: primaryNsc || findPrimaryNscContact(),\n      };\n    }\n\n    throw new Error(\n      'Could not resolve Account. Reload the page and open the Details tab so Account is visible.'\n    );\n  }\n\n  async function loadRecentSurveyMeta(accountId) {\n    emitProgress('Loading survey list for this account…');\n    const records = await relatedListAll(accountId, 'WOH_Survey_Results__r', RELATED_FIELDS);\n    const sorted = [...records].sort((a, b) => sortKey(b) - sortKey(a));\n    const recent = sorted.slice(0, TOP_N).map((record) => ({\n      survey_result_id: record.id,\n      survey_result_name: fieldValue(record, 'Name') || fieldDisplay(record, 'Name') || '',\n      appointment_id: fieldValue(record, 'Appointment__c') || '',\n      appointment_name: appointmentNameFromRelatedRecord\n        ? appointmentNameFromRelatedRecord(record)\n        : fieldDisplay(record, 'Appointment__c') || '',\n      submitted_at_iso: fieldValue(record, 'Date_Time_Survey_Submitted__c') || '',\n      submitted_at_display: fieldDisplay(record, 'Date_Time_Survey_Submitted__c') || '',\n    }));\n\n    for (const meta of recent) {\n      if (meta.appointment_name || !meta.appointment_id || !uiApiRecordFields) continue;\n      try {\n        const appt = await uiApiRecordFields(meta.appointment_id, ['Name']);\n        const name = fieldDisplay(appt, 'Name') || fieldValue(appt, 'Name') || '';\n        meta.appointment_name = window.WohRequestNumber?.usableAppointmentName\n          ? window.WohRequestNumber.usableAppointmentName(name)\n          : name;\n      } catch (_) {\n        /* keep empty; Request # will not fall back to WOH SR */\n      }\n    }\n\n    return recent;\n  }\n\n  async function scrapeOneSurvey(meta, account, index, total) {\n    emitProgress(`Loading answers ${index}/${total}…`);\n    const feedbackUrl = `${location.origin}/apex/WHT_FeedBackDetail?appointmentId=${encodeURIComponent(meta.appointment_id)}`;\n\n    try {\n      const { html, url } = await fetchFeedbackHtml(meta.appointment_id);\n      const parsed = parseFeedbackHtml(html);\n      return {\n        ok: true,\n        survey_result_id: meta.survey_result_id,\n        survey_result_name: meta.survey_result_name,\n        appointment_id: meta.appointment_id,\n        appointment_name: meta.appointment_name || parsed.req_number || '',\n        appointment_url: meta.appointment_id\n          ? `${location.origin}/lightning/r/Appointment__c/${meta.appointment_id}/view`\n          : '',\n        account_id: account.accountId,\n        account_name: account.accountName,\n        feedback_url: url || feedbackUrl,\n        req_number: parsed.req_number || meta.appointment_name || '',\n        submitted_at: parsed.submitted_at || meta.submitted_at_display,\n        submitted_by: parsed.submitted_by,\n        consultant_name: parsed.consultant_name,\n        product: parsed.product,\n        sub_product: parsed.sub_product,\n        overall_satisfaction: parsed.overall_satisfaction,\n        consultant_satisfaction: parsed.consultant_satisfaction,\n        comments: parsed.comments,\n      };\n    } catch (err) {\n      try {\n        const response = await api.runtime.sendMessage({\n          type: 'SCRAPE_FEEDBACK_TAB_ONLY',\n          appointmentId: meta.appointment_id,\n          feedbackUrl,\n        });\n        if (!response?.ok) throw new Error(response?.error || 'Tab scrape failed');\n        const record = response.record || {};\n        return {\n          ok: true,\n          survey_result_id: meta.survey_result_id,\n          survey_result_name: meta.survey_result_name,\n          appointment_id: meta.appointment_id,\n          appointment_name: meta.appointment_name || record.req_number || '',\n          appointment_url: meta.appointment_id\n            ? `${location.origin}/lightning/r/Appointment__c/${meta.appointment_id}/view`\n            : '',\n          account_id: account.accountId,\n          account_name: account.accountName,\n          feedback_url: feedbackUrl,\n          req_number: record.req_number || meta.appointment_name || '',\n          submitted_at: record.submitted_at || meta.submitted_at_display,\n          submitted_by: record.submitted_by || '',\n          consultant_name: record.consultant_name || '',\n          product: record.product || '',\n          sub_product: record.sub_product || '',\n          overall_satisfaction: record.overall_satisfaction || '',\n          consultant_satisfaction: record.consultant_satisfaction || '',\n          comments: record.comments || '',\n        };\n      } catch (fallbackErr) {\n        return {\n          ok: false,\n          survey_result_id: meta.survey_result_id,\n          survey_result_name: meta.survey_result_name,\n          appointment_id: meta.appointment_id,\n          appointment_name: meta.appointment_name || '',\n          account_id: account.accountId,\n          account_name: account.accountName,\n          feedback_url: feedbackUrl,\n          req_number: meta.appointment_name || '',\n          submitted_at: meta.submitted_at_display,\n          error: String(fallbackErr.message || fallbackErr || err.message || err),\n        };\n      }\n    }\n  }\n\n  async function fetchFreshSurveys(account) {\n    const recent = await loadRecentSurveyMeta(account.accountId);\n    if (!recent.length) {\n      const payload = {\n        ok: true,\n        account_id: account.accountId,\n        account_name: account.accountName,\n        account_href: account.accountHref || '',\n        appointment_id: account.appointmentId || '',\n        surveys: [],\n        message: 'No WOH Survey Results found for this Account',\n      };\n      await panel.writeCache(account.accountId, payload);\n      return payload;\n    }\n\n    const surveys = [];\n    for (let i = 0; i < recent.length; i++) {\n      surveys.push(await scrapeOneSurvey(recent[i], account, i + 1, recent.length));\n    }\n\n    const payload = {\n      ok: true,\n      account_id: account.accountId,\n      account_name: account.accountName,\n      account_href: account.accountHref || '',\n      account_source: account.source || '',\n      appointment_id: account.appointmentId || '',\n      surveys,\n    };\n    await panel.writeCache(account.accountId, payload);\n    return payload;\n  }\n\n  function resolvePrimaryNsc(account) {\n    return account?.primaryNsc || findPrimaryNscContact() || null;\n  }\n\n  function withPrimaryNsc(payload, primaryOverride = null) {\n    const primary = primaryOverride || findPrimaryNscContact();\n    const primaryName = primary?.name || '';\n    const surveys = (payload.surveys || []).map((survey) => ({\n      ...survey,\n      is_primary_nsc: Boolean(primaryName && namesMatch(survey.submitted_by, primaryName)),\n    }));\n    const primaryInList = surveys.some((s) => s.ok && s.is_primary_nsc);\n    return {\n      ...payload,\n      primary_nsc_contact: primaryName,\n      primary_nsc_matched: primaryInList,\n      primary_nsc_source: primary?.source || '',\n      primary_nsc_notice:\n        primaryName && !primaryInList\n          ? `${primaryName} (Primary NSC Contact) has not submitted a survey in this recent list.`\n          : '',\n      surveys,\n    };\n  }\n\n  function withCsatAverage(payload) {\n    const summary = window.WohCsatParse?.averageCsatPoints\n      ? window.WohCsatParse.averageCsatPoints(payload.surveys || [])\n      : { average: null, count: 0, display: '', notice: '' };\n    return {\n      ...payload,\n      csat_average: summary.average,\n      csat_average_count: summary.count,\n      csat_average_display: summary.display || '',\n      csat_average_notice: summary.notice || '',\n    };\n  }\n\n  function decoratePayload(payload, { pageContext, primary } = {}) {\n    const next = { ...payload, page_context: pageContext || payload.page_context || 'appointment' };\n    if (next.page_context === 'account') {\n      return withCsatAverage(next);\n    }\n    return withPrimaryNsc(next, primary);\n  }\n\n  async function showAccountSurveysPanel({ forceRefresh = false } = {}) {\n    const pageContext = detectPageContext();\n    if (!pageContext) {\n      throw new Error('Open an Appointment (REQ) or Account record page first');\n    }\n\n    panel.setStatus('Resolving Account…');\n    const account =\n      pageContext === 'account'\n        ? await resolveAccountRecord()\n        : await resolveAccount(parseAppointmentId(location.href));\n    const primary = pageContext === 'appointment' ? resolvePrimaryNsc(account) : null;\n\n    if (!forceRefresh) {\n      const cached = await panel.readCache(account.accountId);\n      const payload = cached?.payload;\n      const staleWohSr =\n        payload &&\n        (payload.surveys || []).some((survey) => {\n          if (survey.appointment_name) return false;\n          if (!isSurveyResultName?.(survey.survey_result_name)) return false;\n          return !extractAppointmentNumber?.(survey.req_number);\n        });\n      if (payload && !staleWohSr) {\n        const decorated = decoratePayload(payload, { pageContext, primary });\n        panel.showPayload(decorated, { fromCache: true });\n        return { ok: true, cached: true, ...decorated };\n      }\n    }\n\n    panel.setStatus('Loading survey list…');\n    const payload = decoratePayload(await fetchFreshSurveys(account), { pageContext, primary });\n    panel.showPayload(payload, { fromCache: false });\n    return payload;\n  }\n\n  async function runPanelFlow(options = {}) {\n    const now = Date.now();\n    const stale = inflight && now - inflightStartedAt > INFLIGHT_STALE_MS;\n\n    if (inflight && !stale && !options.forceRefresh) {\n      return inflight;\n    }\n\n    if (inflight && (stale || options.forceRefresh)) {\n      inflight = null;\n    }\n\n    panel?.setStatus?.('Loading surveys…');\n    inflightStartedAt = now;\n    inflight = showAccountSurveysPanel(options)\n      .catch((err) => {\n        panel.showError(err.message || err);\n        return { ok: false, error: String(err.message || err) };\n      })\n      .finally(() => {\n        inflight = null;\n      });\n    return inflight;\n  }\n\n  api.runtime.onMessage.addListener((message, _sender, sendResponse) => {\n    if (\n      message.type === 'SHOW_ACCOUNT_SURVEYS_PANEL' ||\n      message.type === 'REQUEST_ACCOUNT_SURVEYS' ||\n      message.type === 'SHOW_ACCOUNT_SURVEYS'\n    ) {\n      panel?.setStatus?.('Loading surveys…');\n      runPanelFlow({ forceRefresh: Boolean(message.forceRefresh) })\n        .then((data) => sendResponse(data))\n        .catch((err) => sendResponse({ ok: false, error: String(err.message || err) }));\n      return true;\n    }\n\n    if (message.type === 'PING_APPOINTMENT') {\n      sendResponse({\n        ok: true,\n        appointmentId: parseAppointmentId(location.href),\n        accountId: parseAccountId(location.href),\n        page_context: detectPageContext(),\n      });\n      return false;\n    }\n  });\n\n  window.addEventListener('woh-survey-refresh', () => {\n    runPanelFlow({ forceRefresh: true });\n  });\n})();\n"];
  const session = await page.context().newCDPSession(page);
  async function run(expression) {
    const result = await session.send('Runtime.evaluate', {
      expression,
      awaitPromise: false,
      returnByValue: true,
    });
    if (result.exceptionDetails) {
      const text = result.exceptionDetails.text || 'eval failed';
      const desc = (result.exceptionDetails.exception && result.exceptionDetails.exception.description) || '';
      throw new Error((text + ' ' + desc).slice(0, 800));
    }
    return result.result && result.result.value;
  }

  await run(`(() => {
    const listeners = [];
    const storage = {};
    globalThis.browser = {
      storage: {
        local: {
          async get(keys) {
            if (keys == null) return { ...storage };
            if (typeof keys === 'string') return { [keys]: storage[keys] };
            const out = {};
            for (const key of Object.keys(keys)) out[key] = storage[key];
            return out;
          },
          async set(obj) { Object.assign(storage, obj); },
        },
      },
      runtime: {
        lastError: null,
        onMessage: { addListener(fn) { listeners.push(fn); } },
        sendMessage(message) {
          return (async () => {
            if (message && message.type === 'FETCH_FEEDBACK_HTML' && globalThis.WohSfApi && globalThis.WohSfApi.fetchFeedbackHtmlDirect) {
              try {
                const result = await globalThis.WohSfApi.fetchFeedbackHtmlDirect(message.appointmentId);
                return { ok: true, html: result.html, url: result.url };
              } catch (err) {
                return { ok: false, error: String(err.message || err) };
              }
            }
            return { ok: false, error: 'Unhandled ' + (message && message.type) };
          })();
        },
      },
      __listeners: listeners,
    };
  })();`);

  for (const source of sources) await run(source);

  const ready = await run(`({
    listeners: (globalThis.browser.__listeners || []).length,
    isAccount: Boolean(window.WohScrape && window.WohScrape.isAccountUrl && window.WohScrape.isAccountUrl(location.href)),
    accountId: (window.WohScrape && window.WohScrape.parseAccountId && window.WohScrape.parseAccountId(location.href)) || '',
  })`);

  await run(`(() => {
    const message = { type: 'SHOW_ACCOUNT_SURVEYS_PANEL', forceRefresh: true };
    for (const fn of globalThis.browser.__listeners || []) fn(message, {}, function () {});
    return true;
  })()`);

  return ready;
}
